import{_ as u,a0 as f,w as l,s as a,I as e,x as n,a1 as o,A as i,ao as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"每日 Ubuntu 小技巧——在 Ubuntu 中手动安装任何版本的 Firefox | LCTT x X-CMD","titleTemplate":false,"description":"每日 Ubuntu 小技巧——在 Ubuntu 中手动安装任何版本的 Firefox | LCTT (201402) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每日 Ubuntu 小技巧——在 Ubuntu 中手动安装任何版本的 Firefox | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每日 Ubuntu 小技巧——在 Ubuntu 中手动安装任何版本的 Firefox | LCTT (201402) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201402/Daily Ubuntu Tips – Manually Install Any Version Of Firefox In Ubuntu","title":"每日 Ubuntu 小技巧——在 Ubuntu 中手动安装任何版本的 Firefox","tag":"201402","desc":""},"relativePath":"201402/Daily Ubuntu Tips – Manually Install Any Version Of Firefox In Ubuntu.md","filePath":"[post].md"}'),s={name:"201402/Daily Ubuntu Tips – Manually Install Any Version Of Firefox In Ubuntu.md"};function x(b,t,d,m,F,U){const r=f("Link");return l(),a("div",null,[t[17]||(t[17]=e("h1",{id:"每日-ubuntu-小技巧——在-ubuntu-中手动安装任何版本的-firefox",tabindex:"-1"},[n("每日 Ubuntu 小技巧——在 Ubuntu 中手动安装任何版本的 Firefox "),e("a",{class:"header-anchor",href:"#每日-ubuntu-小技巧——在-ubuntu-中手动安装任何版本的-firefox","aria-label":"Permalink to “每日 Ubuntu 小技巧——在 Ubuntu 中手动安装任何版本的 Firefox”"},"​")],-1)),t[18]||(t[18]=e("p",null,"Firefox 是 Ubuntu 中主要的网络浏览器。它预装在系统中，并添加到默认的 Ubuntu 软件库中以获得 Firefox 最新版本的自动更新。",-1)),t[19]||(t[19]=e("p",null,"大多数用户并不用担心安装或使用 Firefox 的问题，因为没有什么问题了，它已经安装并可以使用。你获取的总是 Firefox 在 Ubuntu 软件库中的版本，除非更新 Canonical 的软件到最新版本。",-1)),t[20]||(t[20]=e("p",null,"现在，如果你想尝试其它的 Firefox 版本，你就必须手动下载并在 Ubuntu 中安装它，这个简短教程将指导你如何正确地在 Ubuntu 中做到这一点。",-1)),t[21]||(t[21]=e("p",null,"因为 Firefox 集成在 Ubuntu 中，如果你试图完全卸载它，很可能会破坏其它东西。因此要安装其它版本的最好办法就是为每个版本分别创建文件夹并进行符号连接。",-1)),t[22]||(t[22]=e("h3",{id:"在-ubuntu-中下载并安装-firefox",tabindex:"-1"},[n("在 Ubuntu 中下载并安装 Firefox "),e("a",{class:"header-anchor",href:"#在-ubuntu-中下载并安装-firefox","aria-label":"Permalink to “在 Ubuntu 中下载并安装 Firefox”"},"​")],-1)),e("p",null,[t[1]||(t[1]=n("如果你想在 Ubuntu 中手动下载最新版本的 Firefox，进入它的",-1)),o(r,{href:"http://www.mozilla.org/en-US/firefox/all/"},{default:i(()=>[...t[0]||(t[0]=[n("下载页面",-1)])]),_:1}),t[2]||(t[2]=n("。通过它你将可以获取到最新版本并安装它。",-1))]),e("p",null,[t[4]||(t[4]=n("如果你想从初始版本安装其它版本的 Firefox，",-1)),o(r,{href:"https://ftp.mozilla.org/pub/mozilla.org/firefox/releases/"},{default:i(()=>[...t[3]||(t[3]=[n("访问这个页面",-1)])]),_:1}),t[5]||(t[5]=n("。在这你将看到从0.8开始的每个版本。",-1))]),t[23]||(t[23]=p(`<p>下载完你想要的版本之后，切换到 home 目录下的下载文件夹，因为 Ubuntu 的大多数文件被下载到了这里。</p><pre><code>cd ~/Downloads
</code></pre><p><img src="http://www.liberiangeek.net/wp-content/uploads/2014/02/firefoxmanualinstall.png" alt=""></p><h3 id="配置-firefox" tabindex="-1">配置 Firefox <a class="header-anchor" href="#配置-firefox" aria-label="Permalink to “配置 Firefox”">​</a></h3><p>由于大多数 Firefox 下载文件以.tar和.bz2格式保存，必须从这些压缩包中提取文件。有很多方法可以在 Ubuntu 中解压缩文件。</p><p>比如我下面使用的命令。很容易从.tar和.bz2中提取文件。</p><pre><code>tar -xjf firefox*.tar.bz2
</code></pre><p>解压后，将会有一个新的 Firefox 文件出现在下载文件夹中。这其中包含了所有的 Firefox 的文件和可执行文件。</p><p>由于我们不想删除当前安装的 Firefox，我们必须给每个版本的 Firefox 创建一个单独的文件夹。因此，对于 Firefox 版本30，使用下面的命令在/opt目录下创建一个包含新 Firefox 内容的文件夹。</p><pre><code>sudo mv firefox/ /opt/firefox30
</code></pre><p>现在，<strong>/opt/firefox30/</strong>目录包含的所有文件都是版本30的。</p><h3 id="创建新的-firefox-可执行符号链接" tabindex="-1">创建新的 Firefox 可执行符号链接 <a class="header-anchor" href="#创建新的-firefox-可执行符号链接" aria-label="Permalink to “创建新的 Firefox 可执行符号链接”">​</a></h3><p>默认情况下，Firefox 的可执行文件在这个路径下：<strong>/user/bin/firefox</strong>。我们想要做的是临时创建一个备份，这样我们就可以使用我们的自定义安装的可执行文件。</p><p>要做到这一点，运行下面的命令。</p><pre><code>sudo mv /usr/bin/firefox /usr/bin/firefox-old
</code></pre><p>现在，我们已经从其默认位置移动了 Firefox 的可执行文件，我们必须将默认位置链接到我们新的自定义安装文件。要做到这一点，运行下面的命令来创建我们版本30的一个符号链接。</p><pre><code>sudo ln -s /opt/firefox30/firefox /usr/bin/firefox
</code></pre><p>这样就设置完成了，我们自定义安装的 Firefox 是 Ubuntu 默认的。每一次启动 Firefox，它将通过之前的新链接加载新的可执行文件。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2014/02/firefoxmanualinstall1.png" alt=""></p><p>以上方法同样适用于 64-bit 版本的 Firefox。</p><hr>`,21)),e("p",null,[t[7]||(t[7]=n("via: ",-1)),o(r,{href:"http://www.liberiangeek.net/2014/02/daily-ubuntu-tips-manually-install-any-version-of-firefox-in-ubuntu/"},{default:i(()=>[...t[6]||(t[6]=[n("http://www.liberiangeek.net/2014/02/daily-ubuntu-tips-manually-install-any-version-of-firefox-in-ubuntu/",-1)])]),_:1})]),e("p",null,[t[10]||(t[10]=n("译者：",-1)),o(r,{href:"https://github.com/yechunxiao19"},{default:i(()=>[...t[8]||(t[8]=[n("乌龙茶",-1)])]),_:1}),t[11]||(t[11]=n(" 校对：",-1)),o(r,{href:"https://github.com/carolinewuyan"},{default:i(()=>[...t[9]||(t[9]=[n("Caroline",-1)])]),_:1})]),e("p",null,[t[14]||(t[14]=n("本文由 ",-1)),o(r,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[12]||(t[12]=[n("LCTT",-1)])]),_:1}),t[15]||(t[15]=n(" 原创翻译，",-1)),o(r,{href:"http://linux.cn/"},{default:i(()=>[...t[13]||(t[13]=[n("Linux中国",-1)])]),_:1}),t[16]||(t[16]=n(" 荣誉推出",-1))])])}const y=u(s,[["render",x]]);export{w as __pageData,y as default};
